// Contenido de B1 y B4–B9, investigadores, glosario, ayuda y metodología.
// Formato de cuerpo: cadena = párrafo; "## " = subtítulo; array = lista; {box:"texto"} = recuadro; {warn:"texto"} = aviso.
// qs: [enunciado, [opciones], índice correcto, explicación]
window.FUNDAMENTOS = [
{s:"que-es-manipular", t:"¿Qué es manipular?", sum:"Definiciones, diferencia con persuadir y el test de transparencia.",
 body:[
 "Manipular es influir en lo que alguien piensa, siente o hace **por vías que evitan su juicio consciente o explotan sus debilidades**, normalmente ocultando la intención y en beneficio de quien manipula. Los filósofos que estudian el tema (Robert Noggle, Anne Barnhill, Cass Sunstein) coinciden en un núcleo: la manipulación no respeta a la otra persona como alguien capaz de decidir por sí mismo.",
 "## Cuatro formas de influir",
 ["**Informar:** dar datos verdaderos y relevantes. La persona decide.","**Persuadir:** ofrecer argumentos y razones verdaderas, de forma abierta. La persona puede evaluarlos y rechazarlos.","**Empujar (nudge):** cambiar cómo se presentan las opciones (orden, opción por defecto) sin prohibir nada ni cambiar los incentivos. Puede ser legítimo si es transparente, fácil de evitar y en interés de la persona.","**Manipular:** influir ocultando la intención, con información falsa o incompleta, o aprovechando sesgos, emociones y vulnerabilidades para que la persona haga lo que no haría si lo viera con claridad."],
 {box:"**El test de transparencia:** ¿funcionaría esta influencia si la otra persona supiera exactamente lo que se está haciendo y por qué? Si la respuesta es no, probablemente es manipulación."},
 "## Lo que la manipulación no es",
 ["No toda influencia emocional es manipulación: una historia verdadera que conmueve puede ser persuasión legítima.","No toda manipulación es consciente: mucha gente repite tácticas aprendidas sin pensarlo.","No es magia: casi todas las técnicas usan mecanismos normales de la mente, y casi todas se pueden reconocer."]
 ],
 qs:[["Según el test de transparencia, una influencia es probablemente manipuladora si…",["funcionaría igual aunque la persona supiera lo que se hace","dejaría de funcionar si la persona supiera lo que se hace","usa alguna emoción","la hace un desconocido"],1,"La manipulación depende de que la persona no vea el mecanismo."],
     ["¿Qué distingue la persuasión de la manipulación?",["La persuasión nunca usa emociones","La persuasión ofrece razones verdaderas abiertamente y respeta la decisión","La manipulación siempre es ilegal","No hay diferencia"],1,"Persuadir respeta la capacidad de decidir; manipular la evita o la explota."],
     ["Un «nudge» puede ser legítimo cuando…",["es oculto","es transparente, fácil de evitar y en interés de la persona","beneficia solo a la empresa","elimina opciones"],1,"Es la condición que propone Thaler: «empujar para el bien»."]]},
{s:"dos-velocidades", t:"Las dos velocidades de la mente", sum:"Pensamiento rápido e intuitivo frente a lento y deliberado (Kahneman).",
 body:[
 "Daniel Kahneman popularizó en *Pensar rápido, pensar despacio* (2011) la distinción entre dos modos de pensar, a los que llamó Sistema 1 y Sistema 2 siguiendo a Keith Stanovich y Richard West.",
 ["**Sistema 1 (rápido):** automático, intuitivo, sin esfuerzo, guiado por asociaciones y emociones. Reconoce caras, lee palabras, reacciona a la urgencia.","**Sistema 2 (lento):** deliberado, consciente, costoso. Calcula, compara, verifica."],
 "La mayor parte del tiempo el sistema rápido funciona bien. Pero tiene atajos previsibles, y **la manipulación consiste a menudo en mantenernos en el modo rápido**: prisa, emoción intensa, distracción, cansancio, demasiadas opciones.",
 {box:"Regla práctica: cuando alguien te mete prisa o te emociona mucho antes de una decisión, es el momento de pasar al modo lento."},
 "Matiz importante: la división en dos «sistemas» es una metáfora útil, no dos partes del cerebro. Algunos investigadores prefieren hablar de un continuo de procesamiento."
 ],
 qs:[["¿Qué modo de pensamiento suelen explotar los manipuladores?",["El lento y deliberado","El rápido e intuitivo","Ninguno","El matemático"],1,"La prisa, la emoción y la distracción mantienen activo el modo rápido."],
     ["¿Qué situación favorece el pensamiento lento?",["Prisa","Emoción intensa","Tiempo y calma para comparar","Cansancio"],2,"El sistema 2 necesita tiempo y recursos."]]},
{s:"probabilidad-de-elaboracion", t:"El modelo de probabilidad de elaboración", sum:"Ruta central y ruta periférica de la persuasión (Petty y Cacioppo, 1986).",
 body:[
 "Richard Petty y John Cacioppo propusieron que un mensaje puede persuadir por dos rutas:",
 ["**Ruta central:** cuando estamos motivados y somos capaces de pensar, evaluamos la calidad de los argumentos. El cambio de actitud es más duradero.","**Ruta periférica:** cuando no estamos motivados o no podemos pensar (prisa, distracción, falta de conocimientos), nos guiamos por señales superficiales: atractivo de la fuente, número de argumentos, autoridad, música, lo que hacen otros."],
 "El experimento del examen general (Petty, Cacioppo y Goldman, 1981) lo mostró: cuando el tema afectaba a los estudiantes, contaban los argumentos; cuando no, contaba el prestigio de quien hablaba.",
 {box:"La manipulación vive en la ruta periférica. Para protegerte, crea las condiciones de la ruta central: tiempo, información y atención."}
 ],
 qs:[["En la ruta periférica, la persuasión depende sobre todo de…",["la calidad de los argumentos","señales superficiales como el atractivo o la autoridad de la fuente","la lógica","los datos"],1,"Es la ruta de los atajos."],
     ["¿Cuándo es más probable la ruta central?",["Cuando el tema nos afecta y tenemos tiempo para pensar","Cuando estamos distraídos","Cuando hay música","Cuando hay prisa"],0,"Motivación y capacidad son las dos condiciones."]]},
{s:"heuristicos-y-sesgos", t:"Atajos mentales y sesgos cognitivos", sum:"Heurísticos de disponibilidad, representatividad y anclaje (Tversky y Kahneman, 1974).",
 body:[
 "Un heurístico es una regla mental rápida que suele funcionar. Un sesgo es el error sistemático que aparece cuando el atajo no encaja con la situación. Amos Tversky y Daniel Kahneman describieron en 1974 tres heurísticos fundamentales:",
 ["**Disponibilidad:** juzgamos lo frecuente por lo fácil que es recordarlo. Las noticias impactantes hacen que sobrestimemos ciertos riesgos.","**Representatividad:** juzgamos por parecido con un estereotipo, ignorando las probabilidades de base.","**Anclaje y ajuste:** partimos de un número inicial y ajustamos poco."],
 "## Sesgos que la manipulación aprovecha",
 ["**Sesgo de confirmación:** buscamos y creemos lo que confirma lo que ya pensamos.","**Aversión a la pérdida:** perder duele más que ganar lo mismo (base del encuadre y de la urgencia).","**Coste hundido:** seguimos con algo porque ya invertimos en ello.","**Efecto de verdad ilusoria:** lo repetido parece verdadero.","**Efecto halo:** un rasgo positivo (belleza, simpatía) tiñe el juicio sobre todo lo demás.","**Exceso de confianza:** «A mí no me engañan»."],
 {box:"Conocer los sesgos no basta para eliminarlos, pero sí para diseñar defensas: listas de comprobación, pausas, segundas opiniones."}
 ],
 qs:[["El heurístico de disponibilidad consiste en…",["juzgar la frecuencia por la facilidad para recordar ejemplos","partir de un número inicial","parecerse a un estereotipo","repetir"],0,"Por eso las noticias llamativas distorsionan la percepción del riesgo."],
     ["¿Qué sesgo explica que sigamos en un mal negocio porque ya pagamos mucho?",["Efecto halo","Coste hundido","Anclaje","Mera exposición"],1,"Lo gastado no debería influir en la decisión futura."]]},
{s:"emociones", t:"Emociones y manipulación", sum:"Miedo, culpa, vergüenza, deseo y urgencia como palancas.",
 body:[
 "Las emociones son información valiosa, pero también reducen la capacidad de reflexión cuando son intensas. La manipulación suele usar cinco:",
 ["**Miedo:** paraliza o empuja a actuar rápido. Los mensajes de miedo funcionan mejor cuando incluyen una solución fácil… que el manipulador vende (metaanálisis de Witte y Allen, 2000).","**Culpa:** obliga a reparar, aunque no haya falta real (chantaje emocional).","**Vergüenza:** lleva a ocultar y a obedecer para evitar la exposición (estafas de extorsión, sectas).","**Deseo y esperanza:** de amor, dinero, salud o estatus; base de las estafas del amor y de inversión.","**Urgencia:** la emoción del tiempo. Reduce la comparación y la consulta."],
 {box:"Técnica de defensa: nombra la emoción en voz alta o por escrito («Me están asustando»). Ponerle nombre ayuda a recuperar el control (Lieberman y otros, 2007)."}
 ],
 qs:[["¿Por qué los manipuladores combinan miedo con una solución rápida?",["Porque el miedo con una salida fácil empuja a actuar sin pensar","Porque es ilegal","Porque el miedo no funciona","Por casualidad"],0,"Es el patrón de muchas estafas y anuncios."],
     ["Una defensa útil ante una emoción intensa provocada es…",["decidir de inmediato","nombrar la emoción y aplazar la decisión","ignorar toda emoción siempre","compartir el mensaje"],1,"Nombrar y aplazar devuelve el control al pensamiento lento."]]},
{s:"necesidades-sociales", t:"Necesidades sociales", sum:"Pertenencia, aprobación, estatus y coherencia.",
 body:[
 "Somos animales sociales. Necesitamos pertenecer (Baumeister y Leary, 1995), ser aprobados, tener estatus y ser coherentes con lo que decimos. Estas necesidades son sanas, pero cada una abre una puerta a la manipulación:",
 ["**Pertenencia:** el miedo al rechazo explica la conformidad (Asch) y el poder de las sectas y los grupos cerrados.","**Aprobación:** buscamos agradar; el halago y la simpatía bajan las defensas.","**Estatus:** los productos y grupos «exclusivos» explotan el deseo de destacar.","**Coherencia:** queremos actuar de acuerdo con nuestros compromisos previos (pie en la puerta, bola baja, disonancia cognitiva)."],
 {box:"Tener varias fuentes de pertenencia (familia, amigos, actividades) es una de las mejores protecciones: quien depende de un solo grupo es más vulnerable a ese grupo."}
 ],
 qs:[["¿Qué necesidad explota sobre todo el aislamiento que practican las sectas?",["Pertenencia","Hambre","Sueño","Curiosidad"],0,"Si el grupo es tu única fuente de pertenencia, salir cuesta muchísimo."],
     ["La técnica del pie en la puerta aprovecha sobre todo la necesidad de…",["estatus","coherencia","miedo","sueño"],1,"Queremos actuar de acuerdo con lo que ya aceptamos."]]},
{s:"principios-cialdini", t:"Los principios de influencia de Cialdini", sum:"Reciprocidad, compromiso y coherencia, prueba social, autoridad, simpatía, escasez y unidad.",
 body:[
 "Robert Cialdini estudió durante años a vendedores, captadores y publicistas (incluso trabajando de incógnito) y resumió sus tácticas en seis principios en *Influence* (1984). En la edición de 2021 añadió un séptimo.",
 ["**Reciprocidad:** devolvemos lo recibido. Experimento: Regan (1971).","**Compromiso y coherencia:** mantenemos lo que dijimos o hicimos. Experimentos: pie en la puerta, bola baja.","**Prueba social:** hacemos lo que hacen otros, sobre todo si se parecen a nosotros. Experimentos: Asch, toallas de hotel.","**Autoridad:** obedecemos a quien parece experto o legítimo. Experimentos: Milgram, Hofling, uniforme.","**Simpatía:** decimos que sí a quien nos cae bien, se nos parece o nos halaga.","**Escasez:** valoramos lo que escasea o puede perderse. Experimento: galletas de Worchel.","**Unidad (2021):** favorecemos a quien consideramos «de los nuestros» (familia, lugar, identidad)."],
 {box:"Ninguno de estos principios es malo en sí mismo. Se vuelven manipulación cuando son **falsos** (escasez inventada, autoridad fingida, prueba social fabricada) o se usan **contra los intereses** de la persona. Ver Influencia ética."}
 ],
 qs:[["¿Qué principio añadió Cialdini en 2021?",["Escasez","Unidad","Autoridad","Reciprocidad"],1,"La unidad: la identidad compartida."],
     ["«Quedan solo 2 plazas» apela al principio de…",["autoridad","escasez","reciprocidad","simpatía"],1,"Si es falso, es escasez falsa."],
     ["Los principios de Cialdini son manipulación cuando…",["se usan siempre","son falsos o van contra los intereses de la persona","se usan en ventas","se explican"],1,"La misma palanca puede ser honesta o engañosa."]]},
{s:"quien-es-vulnerable", t:"¿Quién es más vulnerable?", sum:"Todos lo somos; la situación importa más que la inteligencia.",
 body:[
 "Una creencia muy extendida es que solo caen las personas ingenuas o poco inteligentes. La investigación no lo apoya:",
 ["Las víctimas de estafas de inversión suelen tener **más** formación financiera que la media (estudio de la FINRA Foundation, 2013).","La inteligencia ayuda a construir mejores justificaciones de lo que ya creemos (razonamiento motivado).","Expertos como radiólogos y jueces caen en sesgos como la ceguera inatencional o el anclaje."],
 "## Factores situacionales que aumentan la vulnerabilidad",
 ["Cansancio, estrés, prisa y sobrecarga.","Soledad, duelo, ruptura o cambio vital (mudanza, despido, jubilación).","Problemas económicos o de salud.","Confianza excesiva en una persona o institución.","Exceso de confianza: «a mí no me pasaría»."],
 {box:"La pregunta útil no es «¿soy fácil de manipular?», sino «¿en qué momentos estoy más expuesto?». Ahí conviene activar las defensas."}
 ],
 qs:[["Según la investigación, ¿qué factor influye más en la vulnerabilidad a la manipulación?",["La inteligencia","La situación (cansancio, soledad, prisa, estrés)","El signo del zodiaco","El nivel de estudios"],1,"Los factores situacionales pesan más que los rasgos fijos."],
     ["La creencia «a mí no me engañan»…",["protege","aumenta la vulnerabilidad","no influye","es siempre verdad"],1,"El exceso de confianza baja las defensas."]]}
];

window.INVISIBLE = [
{t:"Arquitectura de la elección", body:["Richard Thaler y Cass Sunstein (*Un pequeño empujón*, 2008) llamaron «arquitectura de la elección» a la forma en que se presentan las opciones: el orden, la opción por defecto, el número de alternativas, cómo se describen. No existe una presentación neutral: alguien decide. El estudio de la donación de órganos (Johnson y Goldstein, 2003) muestra que cambiar la opción por defecto puede cambiar la conducta de casi toda una población."], exp:["johnson-goldstein-defecto","tversky-kahneman-encuadre","nisbett-wilson-saber-mas"]},
{t:"Diseño persuasivo de aplicaciones", body:["B. J. Fogg, de la Universidad de Stanford, propuso que la conducta ocurre cuando coinciden motivación, capacidad y un desencadenante (modelo B = MAP). Nir Eyal (*Hooked*, 2014) describió el «modelo del gancho»: desencadenante → acción → recompensa variable → inversión. Las recompensas variables (no saber qué encontrarás al deslizar) se basan en el refuerzo intermitente estudiado por B. F. Skinner. Estos modelos pueden servir para crear buenos hábitos, pero también para maximizar el tiempo de uso contra el interés del usuario."], exp:["facebook-contagio-emocional"], tec:["desplazamiento-infinito","notificaciones-ansiedad"]},
{t:"Algoritmos y burbujas de filtro", body:["Eli Pariser (2011) advirtió que los algoritmos de personalización nos encierran en «burbujas» que solo muestran lo que confirma nuestras ideas. La evidencia posterior matiza el tamaño del efecto: estudios en Facebook (Bakshy y otros, 2015) y los grandes experimentos con usuarios de Meta durante las elecciones de EE. UU. de 2020 (Guess y otros, 2023, en Science y Nature) encontraron que las propias elecciones de los usuarios pesan más que el algoritmo y que cambiar el algoritmo durante unos meses no cambió de forma notable la polarización. El algoritmo sí influye en qué contenidos se ven y en cuánto tiempo se pasa en la plataforma."], exp:["epstein-buscadores","vosoughi-desinformacion-twitter"]},
{t:"Microsegmentación política: el caso Cambridge Analytica", body:["En 2018, The Guardian, The New York Times y The Observer revelaron que la consultora Cambridge Analytica había obtenido datos de hasta 87 millones de perfiles de Facebook a través de una aplicación de test de personalidad (creada por el investigador Aleksandr Kogan), en su mayoría sin el consentimiento de los afectados. La empresa afirmaba poder influir en votantes con mensajes adaptados a su personalidad («psicografía»).","**Lo que se sabe:** la recogida masiva de datos ocurrió y tuvo consecuencias: la FTC multó a Facebook con 5000 millones de dólares (2019), la autoridad británica de protección de datos le impuso la multa máxima entonces posible (500 000 libras) y Cambridge Analytica cerró en 2018.","**Lo que no se sabe:** no hay pruebas sólidas de que su «psicografía» cambiara votos de forma significativa. La investigación sobre microsegmentación encuentra efectos persuasivos generalmente pequeños. El peligro principal es la opacidad: mensajes distintos para cada grupo, sin debate público."], tec:["microsegmentacion"]},
{t:"Publicidad nativa y marketing de influencia no declarado", body:["La publicidad nativa imita el formato del contenido editorial (artículos, vídeos, publicaciones) para que no se perciba como anuncio. Los estudios muestran que muchas personas no identifican el contenido patrocinado, incluso cuando lleva etiqueta (Wojdynski y Evans, 2016). En la UE y en EE. UU., ocultar que un contenido es publicidad es una práctica comercial engañosa: los influencers deben indicarlo claramente."], tec:["autoridad-falsa","prueba-social-falsa"]},
{t:"Memoria manipulable", body:["La memoria no es una grabación: se reconstruye cada vez que recordamos. Preguntas sugestivas (Loftus y Palmer), información posterior engañosa y la repetición de sucesos falsos por fuentes de confianza pueden alterar recuerdos o crear otros nuevos. Esto es relevante para testimonios, interrogatorios, terapias sugestivas (la polémica de los «recuerdos recuperados» en los años noventa) y relaciones con luz de gas."], exp:["loftus-palmer-choque","loftus-centro-comercial","roediger-mcdermott-drm"], tec:["gaslighting"]},
{t:"Ceguera inatencional y a la elección", body:["Vemos mucho menos de lo que creemos. La ceguera inatencional (el gorila invisible) y la ceguera al cambio muestran que lo que no está en el foco de atención puede pasar inadvertido. La ceguera a la elección muestra que podemos defender como propia una decisión que no tomamos. Los magos, los carteristas y algunos vendedores lo saben bien: dirigen la atención hacia un punto mientras el cambio ocurre en otro."], exp:["simons-chabris-gorila","simons-levin-puerta","johansson-hall-ceguera-eleccion"]},
{t:"Lo que NO funciona: mitos sobre la manipulación oculta", body:["Muchos de los miedos populares a la manipulación «invisible» no tienen base:",["**Mensajes subliminales:** el famoso experimento de Vicary fue un fraude; los efectos de laboratorio son pequeños, breves y requieren una necesidad previa.","**Cintas subliminales de autoayuda:** no funcionan; lo que cambia la experiencia es la etiqueta.","**Mensajes al revés en canciones:** no hay pruebas de que influyan en la conducta (Vokey y Read, 1985).","**PNL:** sin apoyo empírico.","**Priming conductual espectacular:** muchos estudios no se replicaron."],"La manipulación eficaz suele estar **a la vista**: precios, prisas, emociones, opciones por defecto, repetición, presión social. Por eso se puede aprender a reconocerla."], exp:["vicary-subliminal","karremans-subliminal-marca","greenwald-cintas-subliminales","bargh-priming-vejez","pnl"]},
{t:"Señales generales de influencia que no notas", body:[["**Prisa artificial:** plazos que nadie justifica.","**Emoción intensa:** miedo, euforia, indignación o culpa justo antes de decidir.","**Opciones limitadas:** solo dos caminos, o una opción ya marcada.","**Información oculta:** letra pequeña, costes al final, preguntas sin respuesta.","**Aislamiento:** te piden no consultar con nadie.","**Pasos pequeños:** cada uno parece inofensivo."]]},
{t:"Cómo protegerte", body:[["**Pausa:** no decidas con prisa ni con la emoción en lo alto.","**Cambia los valores por defecto:** revisa la privacidad, las renovaciones, las casillas.","**Apaga notificaciones** no esenciales y usa órdenes cronológicos.","**Pregunta «¿quién gana con esto?»** ante cualquier mensaje que te empuja.","**Mira fuera del foco:** ¿qué no me están mostrando?","**Registra tus decisiones y razones** antes de que otros las reinterpreten."]]}
];

window.PROGRAMAS = [
{s:"cointelpro", n:"COINTELPRO", org:"FBI", y:"1956–1971", grp:"fbi",
 d:"Programa de contrainteligencia del FBI, dirigido por J. Edgar Hoover, para vigilar, infiltrar, desacreditar y desorganizar a organizaciones políticas nacionales. Empezó contra el Partido Comunista de EE. UU. y se extendió al movimiento por los derechos civiles (incluido Martin Luther King Jr.), el Partido de las Panteras Negras, grupos nacionalistas puertorriqueños, la Nueva Izquierda, grupos contra la guerra de Vietnam y también grupos supremacistas blancos como el Ku Klux Klan.",
 tac:["Cartas anónimas falsas para provocar conflictos internos o rupturas (incluida la carta anónima enviada a Martin Luther King en 1964 que parecía incitarle al suicidio).","Filtración de información falsa o comprometedora a periodistas.","Sembrar sospechas de que ciertos miembros eran informantes («snitch-jacketing»).","Presiones a empleadores, caseros y familias.","Uso de informantes infiltrados; un informante del FBI facilitó el plano del apartamento de Fred Hampton antes de la redada policial de 1969 en la que murió."],
 desc:"El 8 de marzo de 1971, un grupo de activistas que se hacía llamar Comisión Ciudadana para Investigar al FBI robó documentos de una oficina del FBI en Media (Pensilvania) y los envió a la prensa. Uno de ellos mencionaba «COINTELPRO». El periodista Carl Stern obtuvo más documentos mediante la ley de libertad de información.",
 inv:["Comité Church del Senado de EE. UU. (1975–1976), Informe final, libro III: «Supplementary Detailed Staff Reports on Intelligence Activities and the Rights of Americans».","Comité Pike de la Cámara de Representantes (1975–1976)."],
 cons:"El Comité Church concluyó que el FBI había llevado a cabo «una sofisticada operación de vigilancia» que violaba derechos constitucionales. Se aprobaron las directrices del fiscal general Edward Levi (1976), se crearon comités permanentes de inteligencia en el Congreso y se aprobó la ley FISA (1978).",
 lec:"Las tácticas de COINTELPRO (desinformación, sembrar desconfianza dentro de los grupos, cartas falsas) son técnicas de manipulación aplicadas por un Estado. Su descubrimiento muestra el valor de la prensa libre y de la supervisión parlamentaria.",
 src:["U.S. Senate (1976). Final Report of the Select Committee to Study Governmental Operations with Respect to Intelligence Activities, Book III.","Medsger, B. (2014). The Burglary. Knopf."]},
{s:"negociacion-en-crisis", n:"Unidad de Negociación en Crisis", org:"FBI", y:"Desde los años setenta", grp:"fbi",
 d:"El FBI formó negociadores de rehenes desde los años setenta. Tras los asedios de Ruby Ridge (1992) y Waco (1993), cuyo desenlace fue muy criticado, el FBI creó en 1994 el Grupo de Respuesta a Incidentes Críticos (CIRG), que incluye la Unidad de Negociación en Crisis.",
 tac:["**Modelo de la escalera del cambio de conducta** (Vecchi, Van Hasselt y Romano, 2005): 1) escucha activa, 2) empatía, 3) relación de confianza (rapport), 4) influencia, 5) cambio de conducta. No se puede saltar escalones.","Habilidades de escucha activa: preguntas abiertas, paráfrasis, resumen, etiquetar emociones («parece que te sientes traicionado»), pausas, reflejar las últimas palabras."],
 desc:"Modelo publicado en revistas científicas y en el FBI Law Enforcement Bulletin.",
 inv:["Vecchi, G. M., Van Hasselt, V. B., & Romano, S. J. (2005). Crisis (hostage) negotiation. Aggression and Violent Behavior, 10(5), 533–551."],
 cons:"La negociación en crisis es un ejemplo de **influencia ética**: el objetivo (salvar vidas) es compartido y la influencia se basa en escuchar y comprender, no en engañar. Chris Voss, exnegociador del FBI, divulgó estas técnicas en *Rompe la barrera del no* (2016).",
 lec:"La influencia más eficaz en situaciones extremas empieza por escuchar. Ver Influencia ética.",
 src:["Vecchi y otros (2005).","Voss, C., & Raz, T. (2016). Never Split the Difference."]},
{s:"ciencias-del-comportamiento", n:"Unidad de Ciencias del Comportamiento", org:"FBI", y:"Desde 1972", grp:"fbi",
 d:"Creada en 1972 en la academia del FBI en Quantico (Virginia), con agentes como Howard Teten y Patrick Mullany. A finales de los setenta y principios de los ochenta, Robert Ressler, John Douglas y la investigadora Ann Wolbert Burgess entrevistaron a decenas de asesinos encarcelados para el Proyecto de Investigación de la Personalidad Criminal. Hoy sus funciones se reparten en varias unidades del Centro Nacional para el Análisis de Delitos Violentos (NCAVC).",
 tac:["Elaboración de perfiles criminales a partir de la escena del crimen.","Entrevistas estructuradas a delincuentes.","Formación en entrevista y comportamiento."],
 desc:"Su trabajo se hizo célebre gracias a libros, películas (*El silencio de los corderos*) y series (*Mindhunter*).",
 inv:["Snook, B., et al. (2007). Taking stock of criminal profiling. Criminal Justice and Behavior, 34(4), 437–453."],
 cons:"**Límites científicos:** las revisiones sistemáticas (Snook y otros, 2007) concluyen que la precisión de los perfiles es limitada, que se basa en muestras pequeñas y que su apariencia de exactitud se debe en parte a afirmaciones vagas que parecen acertar (efecto Barnum).",
 lec:"Una técnica puede parecer infalible por su prestigio y su presencia en el cine, y tener poco apoyo empírico. Ver el efecto de autoridad.",
 src:["Ressler, R., Burgess, A., & Douglas, J. (1988). Sexual Homicide: Patterns and Motives.","Snook y otros (2007)."]},
{s:"hig", n:"Grupo de Interrogatorio de Detenidos de Alto Valor (HIG)", org:"FBI, CIA y Departamento de Defensa", y:"Desde 2009", grp:"fbi",
 d:"Creado en 2009, tras la Orden Ejecutiva 13491 que prohibió los «interrogatorios mejorados» (torturas) usados tras el 11-S. Lo administra el FBI e integra a varias agencias. Además de realizar interrogatorios, financió un programa de investigación científica con más de un centenar de estudios.",
 tac:["Construcción de relación (rapport) y entrevista basada en la información.","Técnicas de memoria como la entrevista cognitiva.","Uso estratégico de las pruebas (técnica SUE).","Evitar la coerción, que contamina la información."],
 desc:"Sus conclusiones se han publicado en revistas científicas y en el informe *Interrogation: A Review of the Science* (2016).",
 inv:["HIG (2016). Interrogation: A Review of the Science.","Meissner y otros (2014)."],
 cons:"Su investigación concluyó que los interrogatorios basados en el diálogo, la relación y la obtención de información son **más eficaces** que los coercitivos para obtener información fiable.",
 lec:"Incluso cuando se trata de obtener información de enemigos, la manipulación coercitiva funciona peor que la influencia basada en el respeto.",
 src:["HIG (2016).","Brandon, S. E., et al. (2019). The High-Value Detainee Interrogation Group (HIG): Inception, evolution, and impact."]},
{s:"confesiones-falsas", n:"Confesiones falsas e interrogatorios", org:"Policías de EE. UU. y de otros países", y:"Siglos XX–XXI", grp:"fbi",
 d:"La **técnica Reid**, desarrollada desde los años cincuenta por John E. Reid y Fred Inbau, ha sido el método de interrogatorio más difundido en EE. UU. Incluye un interrogatorio acusatorio en nueve pasos con confrontación, minimización (ofrecer excusas morales) y maximización (exagerar las pruebas). La policía estadounidense puede legalmente mentir sobre las pruebas.",
 tac:["Aislamiento prolongado y cansancio.","Presentar pruebas falsas («tenemos tus huellas»).","Minimización: «cualquiera habría hecho lo mismo».","Promesas implícitas de clemencia.","Especial riesgo con menores y personas con discapacidad intelectual."],
 desc:"Las pruebas de ADN demostraron la inocencia de cientos de condenados. Según el Innocence Project, alrededor de **un 29 %** de las exoneraciones por ADN en EE. UU. incluían una confesión falsa.",
 inv:["Kassin, S. M., et al. (2010). Police-induced confessions: Risk factors and recommendations. Law and Human Behavior, 34(1), 3–38.","Caso de los «Cinco de Central Park» (1989): cinco adolescentes condenados por una violación tras largos interrogatorios; exonerados en 2002 cuando el verdadero autor, Matías Reyes, confesó y el ADN lo confirmó. Recibieron una indemnización de 41 millones de dólares en 2014."],
 cons:"El Reino Unido adoptó en 1992 el **modelo PEACE** (Preparación y planificación, Encuentro y explicación, Relato, Cierre, Evaluación), no acusatorio y centrado en obtener información. Los **Principios de Méndez** (2021) promueven internacionalmente las entrevistas no coercitivas. Algunos estados de EE. UU. prohibieron mentir a menores en interrogatorios.",
 lec:"Las mismas técnicas de presión que producen confesiones falsas aparecen en otras formas de manipulación: aislamiento, cansancio, pruebas falsas, minimización.",
 src:["Innocence Project: False Confessions.","Principles on Effective Interviewing for Investigations and Information Gathering (Principios de Méndez, 2021)."]},
{s:"mkultra", n:"Proyecto MKUltra", org:"CIA", y:"1953–1973", grp:"gob", cw:true,
 d:"Programa de la CIA aprobado en 1953 por su director, Allen Dulles, y dirigido por el químico Sidney Gottlieb, para investigar el control del comportamiento, en plena Guerra Fría y por miedo a que la URSS y China tuvieran técnicas de «lavado de cerebro». Incluyó unos 150 subproyectos en universidades, hospitales y prisiones, a menudo a través de fundaciones pantalla.",
 tac:["Administración de LSD y otras drogas, en muchos casos sin consentimiento ni conocimiento de los afectados.","Privación sensorial, hipnosis y electrochoques.","Operación Midnight Climax: pisos francos donde se administraba LSD a personas sin su conocimiento.","En Canadá, el psiquiatra Ewen Cameron aplicó en el Allan Memorial Institute de Montreal técnicas de «despatronización» (electrochoques intensivos, sueño inducido, mensajes repetidos), financiado en parte por la CIA."],
 desc:"En 1973, el director de la CIA Richard Helms ordenó destruir la mayoría de los archivos. En 1977 apareció un lote de unos 20 000 documentos financieros que se habían archivado por error, obtenidos a través de la ley de libertad de información.",
 inv:["Comisión Rockefeller (1975).","Comité Church (1975–1976).","Audiencia conjunta del Comité Selecto de Inteligencia del Senado y del Subcomité de Salud (agosto de 1977): «Project MKULTRA, the CIA's Program of Research in Behavioral Modification»."],
 cons:"Al menos una persona murió en circunstancias relacionadas con el programa: el científico Frank Olson (1953), tras recibir LSD sin saberlo. El Gobierno de EE. UU. indemnizó a su familia en 1976. Víctimas canadienses llegaron a acuerdos con el Gobierno de EE. UU. en 1988. El programa no encontró ningún método fiable de control mental.",
 lec:"MKUltra es el ejemplo extremo de experimentación sin consentimiento y una de las razones del desarrollo de las normas de ética en la investigación. También muestra que el «control mental» total no existe.",
 src:["U.S. Senate (1977). Project MKULTRA, the CIA's Program of Research in Behavioral Modification.","Kinzer, S. (2019). Poisoner in Chief. Henry Holt."]},
{s:"kubark", n:"El manual KUBARK", org:"CIA", y:"1963 (desclasificado en 1997)", grp:"gob", cw:true,
 d:"*KUBARK Counterintelligence Interrogation* es un manual interno de la CIA de 1963 sobre interrogatorios de contrainteligencia («KUBARK» era el nombre en clave de la propia CIA). Se desclasificó en 1997 tras una petición de la ley de libertad de información presentada por el diario The Baltimore Sun, junto con un manual de 1983, *Human Resource Exploitation Training Manual*.",
 tac:["Describe técnicas de interrogatorio «no coercitivas» y «coercitivas».","Entre las coercitivas, menciona la privación sensorial, la amenaza, el miedo, la desorientación y el aislamiento, basándose en estudios de la época (incluidos algunos financiados por la CIA)."],
 desc:"Sale a la luz por solicitud periodística.",
 inv:["National Security Archive (George Washington University): publicación de los manuales."],
 cons:"Se cita en los debates sobre la ética de los interrogatorios porque muestra cómo la psicología se usó para diseñar técnicas de presión, y por su influencia en manuales posteriores usados en América Latina.",
 lec:"El conocimiento psicológico puede usarse para proteger o para dañar; por eso importan los códigos éticos y la supervisión.",
 src:["CIA (1963). KUBARK Counterintelligence Interrogation. National Security Archive."]},
{s:"lavado-de-cerebro-corea", n:"El «lavado de cerebro» y la guerra de Corea", org:"China y Corea del Norte (y estudios de EE. UU.)", y:"1950–1961", grp:"gob",
 d:"El periodista (y colaborador de la CIA) Edward Hunter popularizó en 1950 el término «brainwashing», traducción de una expresión china. Durante la guerra de Corea (1950–1953), algunos prisioneros estadounidenses firmaron confesiones falsas (por ejemplo, sobre guerra bacteriológica) y 21 de ellos rechazaron volver a su país al final de la guerra, lo que causó alarma.",
 tac:["Aislamiento, privación de sueño y hambre.","Sesiones de «autocrítica» y confesión repetidas.","Recompensas por colaborar y castigos por resistirse.","Presión del grupo y adoctrinamiento constante."],
 desc:"Varios investigadores entrevistaron a prisioneros liberados y a personas sometidas a «reforma del pensamiento» en China.",
 inv:["Lifton, R. J. (1961). Thought Reform and the Psychology of Totalism (estudio de 25 occidentales y 15 chinos).","Schein, E. H. (1961). Coercive Persuasion. Norton."],
 cons:"Los estudios concluyeron que no existía ninguna técnica mágica: los métodos eran coercitivos (presión física, aislamiento, control total del entorno) y la mayoría de las personas recuperó sus creencias anteriores al salir de ese entorno. El miedo exagerado al «lavado de cerebro» contribuyó a crear MKUltra.",
 lec:"El control total del entorno puede producir conformidad temporal, pero no reprograma a nadie. Los criterios de Lifton siguen siendo útiles para reconocer grupos totalistas.",
 src:["Lifton (1961).","Schein (1961)."]},
{s:"bernays", n:"Edward Bernays y el nacimiento de las relaciones públicas", org:"Empresas y Gobierno de EE. UU.", y:"1917–1950", grp:"gob",
 d:"Edward Bernays (1891–1995), sobrino de Sigmund Freud, trabajó en el Comité de Información Pública (Comité Creel) que hizo propaganda a favor de la participación de EE. UU. en la Primera Guerra Mundial. Después fundó las relaciones públicas modernas y escribió *Crystallizing Public Opinion* (1923) y *Propaganda* (1928), donde defendía que una minoría debía «manipular consciente e inteligentemente» la opinión de las masas.",
 tac:["Campaña de las «antorchas de la libertad» (1929): por encargo de una tabacalera, organizó que mujeres fumaran en el desfile de Pascua de Nueva York presentándolo como un acto feminista.","Uso de supuestos expertos y asociaciones creadas para la ocasión.","Crear acontecimientos noticiosos en lugar de anuncios."],
 desc:"Él mismo describió sus métodos en sus libros y memorias.",
 inv:["Tye, L. (1998). The Father of Spin. Crown.","Documental *The Century of the Self* (Adam Curtis, BBC, 2002)."],
 cons:"Sus métodos se extendieron a la publicidad y la política. Joseph Goebbels tenía en su biblioteca obras de Bernays, según el propio Bernays.",
 lec:"Muchas técnicas de persuasión de masas se diseñaron de forma deliberada y se documentaron abiertamente: conocerlas ayuda a reconocerlas.",
 src:["Bernays, E. (1928). Propaganda. Horace Liveright."]},
{s:"propaganda-nazi", n:"La propaganda nazi", org:"Ministerio de Propaganda del Reich (Alemania)", y:"1933–1945", grp:"gob", cw:true,
 d:"En 1933 se creó el Ministerio del Reich para la Ilustración Pública y la Propaganda, dirigido por Joseph Goebbels. Controló la prensa, la radio, el cine, la literatura y las artes, y organizó una propaganda constante basada en el culto al líder, la creación de un enemigo (los judíos y otros grupos) y la promesa de renacimiento nacional.",
 tac:["Control total de los medios y censura.","Radio barata (Volksempfänger) para llegar a todos los hogares.","Cine de propaganda (*El triunfo de la voluntad*, 1935) y antisemita (*El judío eterno*, 1940).","Repetición de consignas simples; deshumanización del enemigo.","Grandes concentraciones y rituales."],
 desc:"Documentado ampliamente por historiadores a partir de los archivos del régimen y de los juicios de Núremberg.",
 inv:["Museo Conmemorativo del Holocausto de EE. UU. (USHMM): exposición «State of Deception: The Power of Nazi Propaganda».","Welch, D. (2002). The Third Reich: Politics and Propaganda. Routledge."],
 cons:"La propaganda preparó a la población para aceptar la persecución y el genocidio. Su estudio dio origen a buena parte de la investigación sobre persuasión y obediencia, incluidos los estudios de Milgram.",
 lec:"La deshumanización, el chivo expiatorio y el control de la información son señales de alarma que preceden a la violencia masiva.",
 src:["USHMM: State of Deception.","Herf, J. (2006). The Jewish Enemy. Harvard University Press."]},
{s:"medidas-activas", n:"Las «medidas activas» soviéticas", org:"KGB (URSS) y servicios aliados", y:"1950–1991", grp:"gob",
 d:"Las «medidas activas» (aktívnye meropriyátiya) eran operaciones de influencia del KGB: desinformación, falsificaciones de documentos, organizaciones pantalla, uso de periodistas y campañas para dañar la imagen de EE. UU. y sus aliados.",
 tac:["**Operación INFEKTION:** en 1983 un periódico indio, *Patriot*, publicó una carta anónima según la cual el sida había sido creado por el Pentágono. El KGB, con la ayuda de la Stasi de Alemania Oriental, difundió la historia durante años en decenas de países, con un supuesto informe científico de apoyo.","Falsificación de documentos oficiales de EE. UU.","Apoyo encubierto a movimientos y medios afines."],
 desc:"Revelado por desertores, archivos abiertos tras la caída de la URSS y la Stasi, y estudios de servicios de inteligencia. En 1992 el entonces director del servicio de inteligencia exterior ruso, Yevgueni Primakov, reconoció la participación del KGB en la campaña.",
 inv:["Boghardt, T. (2009). Operation INFEKTION: Soviet Bloc Intelligence and Its AIDS Disinformation Campaign. Studies in Intelligence, 53(4).","Rid, T. (2020). Active Measures. Farrar, Straus and Giroux."],
 cons:"La historia del origen artificial del sida sigue circulando décadas después: la desinformación sobrevive a su creador.",
 lec:"La desinformación eficaz mezcla verdades con mentiras, se apoya en desconfianzas reales y se difunde a través de intermediarios que parecen independientes.",
 src:["Boghardt (2009).","Rid (2020)."]},
{s:"desinformacion-contemporanea", n:"Desinformación contemporánea", org:"Varios Estados y actores privados", y:"Desde 2014", grp:"gob",
 d:"Las redes sociales han facilitado campañas de influencia baratas y difíciles de atribuir. Las investigaciones oficiales y académicas han documentado varios casos.",
 tac:["**Injerencia rusa en las elecciones de EE. UU. de 2016:** el informe del fiscal especial Robert Mueller (2019) documentó una campaña en redes de la Agencia de Investigación de Internet (San Petersburgo) con cuentas falsas que se hacían pasar por estadounidenses, y el robo y la filtración de correos por parte del servicio de inteligencia militar ruso (GRU).","Granjas de cuentas y comportamiento inauténtico coordinado detectado por las propias plataformas en decenas de países.","Campañas que clonan medios reales (por ejemplo, la campaña «Doppelgänger» detectada desde 2022 en Europa)."],
 desc:"Investigaciones de fiscales, comités parlamentarios, plataformas e investigadores independientes.",
 inv:["Mueller, R. S. (2019). Report on the Investigation into Russian Interference in the 2016 Presidential Election, vol. I.","Comité de Inteligencia del Senado de EE. UU. (2019). Russian Active Measures Campaigns and Interference in the 2016 U.S. Election, vol. 2.","Servicio Europeo de Acción Exterior: EUvsDisinfo (desde 2015)."],
 cons:"Se crearon unidades de lucha contra la desinformación (UE, OTAN), normas de transparencia para plataformas (Ley de Servicios Digitales de la UE) y sanciones. El efecto real de estas campañas en el voto sigue siendo debatido: su objetivo principal suele ser polarizar y erosionar la confianza.",
 lec:"No todo lo que parece una opinión popular lo es. Ver granjas de bots y desinformación.",
 src:["Mueller (2019).","U.S. Senate Select Committee on Intelligence (2019)."]},
{s:"operaciones-psicologicas", n:"La psicología en la guerra: operaciones psicológicas", org:"Ejércitos de muchos países", y:"Siglo XX–XXI", grp:"gob",
 d:"Las operaciones psicológicas (PSYOP) son actividades militares que buscan influir en las emociones, motivaciones y conductas de audiencias extranjeras: tropas enemigas, población civil o aliados.",
 tac:["Panfletos lanzados desde aviones invitando a rendirse (usados masivamente en las dos guerras mundiales, Corea y Vietnam).","Emisiones de radio y altavoces.","Engaño militar: la unidad estadounidense conocida como «Ejército Fantasma» simuló en la Segunda Guerra Mundial tropas inexistentes con tanques hinchables y sonidos grabados.","En Vietnam, la Operación «Alma Errante» difundía de noche grabaciones que imitaban voces de espíritus de muertos."],
 desc:"Doctrina militar pública (manuales de campaña) y estudios históricos.",
 inv:["Linebarger, P. M. A. (1948). Psychological Warfare.","U.S. Army Field Manual FM 3-53, Military Information Support Operations."],
 cons:"Los Estados democráticos prohíben normalmente dirigir estas operaciones contra su propia población. Las fronteras entre propaganda exterior e interior se difuminan en internet.",
 lec:"Las técnicas de guerra psicológica (miedo, desmoralización, desinformación) son las mismas que aparecen a pequeña escala en otras formas de manipulación.",
 src:["Linebarger (1948)."]},
{s:"lecciones", n:"Lecciones: cómo se descubre y se frena la manipulación de Estado", org:"—", y:"—", grp:"gob",
 d:"Casi todos los programas de esta sección salieron a la luz gracias a la combinación de varios contrapoderes:",
 tac:["**Prensa libre:** los documentos de Media llegaron a la prensa; el caso Cambridge Analytica lo destaparon periodistas.","**Denunciantes:** personas de dentro que revelan abusos (como Christopher Wylie en el caso Cambridge Analytica).","**Comités de supervisión:** el Comité Church cambió las reglas de la inteligencia estadounidense.","**Leyes de acceso a la información:** permitieron conocer COINTELPRO, MKUltra y KUBARK.","**Investigación científica independiente:** mostró que la coerción no funciona (HIG) y que muchos «métodos» eran mitos."],
 desc:"—", inv:[], cons:"Los controles democráticos no son perfectos, pero sin ellos estos programas habrían seguido ocultos.",
 lec:"Defender la libertad de prensa, el acceso a la información y la supervisión independiente es una defensa colectiva contra la manipulación.",
 src:["Comité Church (1976).","Schwarz, F. A. O. (2015). Democracy in the Dark. The New Press."]}
];

window.ETICA = [
{s:"test-transparencia", t:"El test de transparencia", body:["Antes de influir en alguien, pregúntate: **¿lo haría igual si la otra persona supiera exactamente qué hago y por qué?** Si tu técnica necesita estar oculta para funcionar, no es ética. Una versión ampliada: ¿podría explicarlo públicamente sin vergüenza? ¿Lo aceptaría si me lo hicieran a mí?"]},
{s:"persuasion-evidencia", t:"Persuasión basada en evidencia", body:["La persuasión ética se dirige a la **ruta central**: argumentos claros, datos verdaderos, reconocer las debilidades de la propia postura y dar tiempo para pensar. La investigación muestra que los mensajes que reconocen los argumentos contrarios y los refutan (mensajes bilaterales) son más creíbles a largo plazo (Allen, 1991; O'Keefe, 1999)."]},
{s:"escucha-activa", t:"Escucha activa y empatía", body:["El modelo de la escalera del cambio de conducta del FBI empieza por escuchar: no hay influencia sin relación, ni relación sin comprensión. La **comunicación no violenta** de Marshall Rosenberg propone cuatro pasos: observar sin juzgar, expresar sentimientos, expresar necesidades y hacer peticiones concretas (no exigencias).",["Haz preguntas abiertas.","Resume lo que entendiste antes de responder.","Nombra la emoción que percibes.","Pide en lugar de exigir: una petición admite un «no»."]], prog:"negociacion-en-crisis"},
{s:"negociacion-principios", t:"Negociación de principios", body:["Roger Fisher y William Ury (Proyecto de Negociación de Harvard) propusieron en *Obtenga el sí* (1981) cuatro principios:",["Separar a las personas del problema.","Centrarse en los intereses, no en las posiciones.","Inventar opciones de beneficio mutuo.","Insistir en criterios objetivos."],"Y conocer tu MAAN (mejor alternativa a un acuerdo negociado): saber qué harás si no hay acuerdo te protege de la presión."]},
{s:"cialdini-etico", t:"Uso ético de los principios de influencia", body:["Cialdini insiste en que los principios pueden usarse con honestidad. La diferencia está en que sean **verdaderos y relevantes**:",["**Prueba social verdadera:** cifras reales y comprobables.","**Escasez real:** solo si de verdad es limitado.","**Autoridad real:** experiencia y credenciales verificables, relevantes para el tema.","**Reciprocidad sin condiciones ocultas:** dar primero sin esperar a cobrar en el momento.","**Simpatía auténtica:** semejanzas reales y elogios sinceros.","**Compromiso voluntario:** que la persona elija libremente, sin trampas posteriores.","**Unidad real:** identidades compartidas de verdad."]]},
{s:"nudges-para-el-bien", t:"«Nudges» para el bien", body:["Richard Thaler firma sus libros con el lema «Nudge for good» (empuja para el bien). Un empujón ético cumple tres condiciones:",["**Transparente:** no depende de que nadie lo note.","**Fácil de evitar:** basta un clic o una palabra para elegir otra cosa.","**En interés de la persona:** según sus propios objetivos, no los de quien empuja."],"Ejemplos: la inscripción automática en planes de pensiones con posibilidad de baja, recordatorios de citas médicas, la opción saludable al principio del menú. Cuando el empujón sirve a la empresa contra el usuario, Thaler lo llama «sludge» (lodo): fricción para que no reclames, no canceles o no compares."]},
{s:"salud-publica", t:"Comunicación en salud pública y seguridad", body:["Los mensajes públicos pueden ser eficaces sin manipular:",["Dar información clara y cifras comprensibles (frecuencias naturales en lugar de porcentajes complejos).","Reconocer la incertidumbre.","Usar normas sociales verdaderas («9 de cada 10 vecinos pagan a tiempo»).","Evitar el miedo sin solución: los mensajes de miedo funcionan solo si ofrecen una acción eficaz y posible (Witte y Allen, 2000).","Preinocular contra la desinformación previsible."]]},
{s:"liderazgo", t:"Liderazgo e influencia en el trabajo sin manipular", body:[["Explica el porqué de las decisiones.","Da crédito público por el trabajo ajeno.","Fija objetivos y criterios claros por escrito.","Acepta el desacuerdo como información, no como deslealtad.","Pide en lugar de presionar con culpa o lealtad.","Cumple lo que prometes: la credibilidad es la base de toda influencia duradera."],"La investigación sobre seguridad psicológica (Amy Edmondson) muestra que los equipos donde se puede discrepar sin miedo aprenden más y cometen menos errores graves."]}
];

window.LIMITES = [
{s:"senales-linea", t:"Señales de que se cruza la línea", body:[["Ocultar la verdadera intención.","Mentir u omitir información relevante.","Explotar una vulnerabilidad (soledad, duelo, enfermedad, edad, adicción).","Impedir pensar: prisa artificial, cansancio, confusión.","Aislar a la persona de otras opiniones.","Amenazar, directa o indirectamente.","Actuar contra los intereses de la otra persona."]]},
{s:"limites-legales", t:"Límites legales (principios generales; varían por país)", body:[{warn:"Esto es información general, no asesoramiento jurídico. Consulta la legislación de tu país o a un profesional."},
 "## Control coercitivo y violencia psicológica",["**Inglaterra y Gales:** el delito de conducta controladora o coercitiva en una relación íntima o familiar existe desde 2015 (Serious Crime Act 2015, sección 76).","**Escocia:** Domestic Abuse (Scotland) Act 2018, que incluye el maltrato psicológico.","**España:** la Ley Orgánica 1/2004 de Medidas de Protección Integral contra la Violencia de Género incluye la violencia psicológica; el Código Penal castiga, entre otros, el maltrato habitual (art. 173.2), las coacciones y el acoso (art. 172 ter)."],
 "## Prácticas comerciales y patrones oscuros",["**Unión Europea:** la Directiva 2005/29/CE prohíbe las prácticas comerciales engañosas y agresivas; la Ley de Servicios Digitales (Reglamento (UE) 2022/2065, art. 25) prohíbe a las plataformas en línea diseños que engañen o manipulen a los usuarios; la Directiva (UE) 2019/2161 prohíbe las reseñas falsas.","**EE. UU.:** la Comisión Federal de Comercio (FTC) persigue prácticas engañosas, como en los casos de Epic Games (2022) y Amazon Prime (2023–2025)."],
 "## Otros delitos",["**Fraude y estafa:** engañar para obtener un beneficio económico.","**Acoso** (también en línea).","**Suplantación de identidad.**","**Extorsión y chantaje.**"]]},
{s:"etica-investigacion", t:"Ética en la investigación", body:["Muchos de los experimentos de este sitio hoy no se aprobarían. Las normas actuales surgieron de abusos documentados:",["**Código de Núremberg (1947):** tras los juicios a médicos nazis; consentimiento voluntario.","**Estudio de Tuskegee (1932–1972):** el Servicio de Salud Pública de EE. UU. dejó sin tratar la sífilis de cientos de hombres afroamericanos para observar la enfermedad, incluso cuando ya existía la penicilina.","**MKUltra (1953–1973):** experimentos sin consentimiento.","**Milgram (1963) y Stanford (1971):** estrés intenso y engaño."],"En 1974 EE. UU. aprobó la National Research Act y en 1979 se publicó el **Informe Belmont**, con tres principios: respeto por las personas (consentimiento informado), beneficencia (minimizar el daño) y justicia (reparto equitativo de cargas y beneficios). Hoy, los comités de ética revisan los estudios con personas, y el engaño solo se permite si es imprescindible, el riesgo es mínimo y se explica después (debriefing)."], prog:"mkultra"},
{s:"etica-profesional", t:"Ética profesional", body:[["**Psicología:** códigos como el de la American Psychological Association o el Código Deontológico del Consejo General de la Psicología de España prohíben el engaño y la explotación de los pacientes.","**Periodismo:** separar información y opinión, verificar, identificar la publicidad.","**Publicidad:** códigos de autorregulación (en España, Autocontrol) que exigen identificar la publicidad y no explotar la credulidad.","**Negociación y mediación:** honestidad, confidencialidad e imparcialidad."]]},
{s:"por-que-sale-caro", t:"Por qué manipular sale caro", body:[["**Daño a las relaciones:** cuando se descubre, la confianza rara vez se recupera del todo.","**Pérdida de reputación:** en un mundo conectado, las tácticas se difunden.","**Efecto bumerán:** la gente que detecta un intento de persuasión se vuelve más resistente (modelo del conocimiento de la persuasión, Friestad y Wright, 1994).","**Consecuencias legales:** multas, indemnizaciones, condenas.","**Coste personal:** vivir de engaños exige vigilancia constante."]]},
{s:"casos-consecuencias", t:"Casos con consecuencias", body:[["**Epic Games (2022):** acuerdo con la FTC de 520 millones de dólares, de los cuales 245 millones fueron devoluciones a usuarios por patrones oscuros que provocaban compras no deseadas en *Fortnite*.","**Amazon Prime (2025):** acuerdo de 2500 millones de dólares con la FTC por inscribir a usuarios en Prime sin su consentimiento claro y dificultar la baja.","**Facebook y Cambridge Analytica:** multa de 5000 millones de dólares de la FTC (2019); cierre de Cambridge Analytica (2018).","**Bernard Madoff:** condenado en 2009 a 150 años de prisión por el mayor esquema Ponzi conocido.","**Inglaterra y Gales:** cientos de condenas cada año por control coercitivo desde 2015."]]}
];

window.AUTODEFENSA = [
{s:"la-pausa", t:"La pausa: la regla de las 24 horas", body:["Casi todas las técnicas de manipulación necesitan que decidas **ya**. La defensa más simple y eficaz es no hacerlo: para cualquier decisión importante tomada bajo presión (compras grandes, firmas, inversiones, transferencias, compromisos), espera al menos 24 horas y consúltalo con alguien de confianza.",{box:"Frase útil: «Nunca decido nada importante el mismo día. Si la oferta es buena, seguirá mañana»."}]},
{s:"preguntas-clave", t:"Preguntas clave", body:[["¿Quién gana con esto?","¿Por qué la prisa?","¿Qué no me están diciendo?","¿Lo decidiría igual con calma, sin emoción y con toda la información?","¿Me dejan consultar con otras personas?","¿Qué pasa si digo que no?"]]},
{s:"inoculacion", t:"Inoculación", body:["Igual que una vacuna expone al sistema inmunitario a una versión debilitada del virus, conocer las técnicas de manipulación de antemano protege contra ellas (McGuire, 1961; Roozenbeek y van der Linden, 2019). Los efectos disminuyen con el tiempo, así que conviene repasar: por eso este sitio tiene demostraciones y un curso."], exp:["mcguire-inoculacion","roozenbeek-bad-news"]},
{s:"alfabetizacion-mediatica", t:"Alfabetización mediática y verificación", body:["Mike Caulfield propuso el método **SIFT** (en inglés, «cribar»):",["**S — Para (Stop):** antes de compartir o creer, detente.","**I — Investiga la fuente:** ¿quién lo publica? ¿Qué dicen otros sobre esa fuente?","**F — Busca mejor cobertura (Find):** ¿lo publican otros medios fiables?","**T — Rastrea el origen (Trace):** busca la cita, el estudio o la imagen original."],"La **lectura lateral** (abrir nuevas pestañas para averiguar qué dicen otros sobre una fuente, en lugar de leerla a fondo) es lo que hacen los verificadores profesionales (Wineburg y McGrew, 2019). Usa la búsqueda inversa de imágenes y consulta verificadores de datos."]},
{s:"atencion-digital", t:"Proteger tu atención digital", body:[["Desactiva las notificaciones no esenciales.","Quita las aplicaciones más absorbentes de la pantalla principal.","Usa órdenes cronológicos cuando la plataforma lo permita.","Revisa la privacidad y los permisos de las aplicaciones.","Rechaza las cookies no necesarias.","Revisa tus suscripciones y cargos cada mes.","Usa la verificación en dos pasos."]]},
{s:"en-las-relaciones", t:"En las relaciones", body:[{warn:"Si estás en peligro inmediato, llama al número de emergencias de tu país (112 en Europa, 911 en gran parte de América)."},["**Registra los hechos:** fechas, frases, mensajes (guárdalos en un lugar seguro, fuera del alcance de la otra persona).","**Cuenta con personas de confianza:** al menos una que sepa lo que pasa.","**Pon límites claros** y observa la reacción: el respeto a un «no» es una buena prueba.","**Infórmate** en servicios especializados: no necesitas estar seguro de que «es maltrato» para llamar.","**Planifica tu seguridad** si decides irte; los servicios especializados pueden ayudarte."],"Ver la página Pedir ayuda."]},
{s:"ayudar-a-otros", t:"Ayudar a alguien que está siendo manipulado", body:[["**No confrontes de forma agresiva:** atacar a la pareja, al grupo o al «gurú» suele hacer que la persona lo defienda y se aleje de ti.","**Mantén el contacto:** eres un salvavidas fuera del entorno manipulador.","**Haz preguntas, no sermones:** «¿Cómo te sientes cuando…?».","**Respeta sus tiempos:** salir de una situación de manipulación suele llevar varios intentos.","**Ofrece ayuda concreta:** un lugar, un teléfono, acompañamiento.","**Cuídate tú también** y busca orientación profesional."]]},
{s:"lista-verificacion", t:"Lista de verificación descargable", body:["Descarga o imprime una lista de señales de manipulación por ámbito para tenerla a mano."], checklist:true}
];

